                         *      Decode 'arg_N' arguments (horrible format)
                         */
                        if (tacacs_decode_args(ctx, out, attr_tacacs_argument_list,
                                               pkt->author_req.arg_cnt, BODY(author_req), p, end) < 0) goto fail;

