                         * +----------------+----------------+----------------+----------------+
                         * |    arg_cnt     |   arg_1_len    |   arg_2_len    |      ...       |
                         * +----------------+----------------+----------------+----------------+
                         * |   arg_N_len    |    user ...
                         * +----------------+----------------+----------------+----------------+
                         * |   port ...
                         * +----------------+----------------+----------------+----------------+
                         * |   rem_addr ...
                         * +----------------+----------------+----------------+----------------+
                         * |   arg_1 ...
                         * +----------------+----------------+----------------+----------------+
                         * |   arg_2 ...
                         * +----------------+----------------+----------------+----------------+
                         * |   ...
                         * +----------------+----------------+----------------+----------------+
                         * |   arg_N ...
                         * +----------------+----------------+----------------+----------------+
                         */

